import fs from'node:fs';import path from'node:path';import assert from'node:assert/strict';
const entries=JSON.parse(fs.readFileSync('outputs/mobile-release-20261012/baseline.json')),out='outputs/mobile-release-20261012';fs.mkdirSync(out+'/fixtures',{recursive:true});const report=[];
for(const e of entries){if(e.id==='clickcore')continue;const html=fs.readFileSync(e.file,'utf8'),cfg=JSON.parse(html.match(/data-loading='([^']+)'/)[1]);assert.equal(cfg.release,'20261012-mobile1');assert(!cfg.pack);assert(html.includes('mobile-performance-v1.js'));const missing=[];for(const f of new Set([...cfg.files,...cfg.images,...cfg.deferredResources,cfg.scene])){const p=path.resolve(path.dirname(e.file),f.split('?')[0]);if(!fs.existsSync(p))missing.push(f);}assert.deepEqual(missing,[],e.id);assert(cfg.aspect>0);assert(cfg.layout.top+cfg.layout.height<=100);
const fixture={...cfg,files:[],scene:'/games/'+path.relative('games',path.resolve(path.dirname(e.file),cfg.scene)).replaceAll('\\','/'),sizes:{}};
fs.writeFileSync(out+'/fixtures/'+e.id+'.html',`<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><script src="/games/shared/load-progress-v1.js?v=20261012-mobile1" data-loading='${JSON.stringify(fixture)}'></script></head><body><script>const session=CxQLoading.create(['a','b'],{label:${JSON.stringify(cfg.label)}});session.ready('a');</script></body></html>`);report.push({id:e.id,file:e.file,resources:cfg.deferredResources.length,files:cfg.files.length,missing});}
const closed=fs.readFileSync('games/click-core/index.html','utf8');assert(closed.includes('暫停開放'));assert(!closed.includes('<script'));assert(!closed.includes('localStorage'));
fs.writeFileSync(out+'/contracts.json',JSON.stringify(report,null,2));console.log('PASS '+report.length+' active loading contracts, all referenced files, staged resource lists, layout bounds; clickcore direct route blocked without save writes.');
